<!-- eslint-disable node/no-callback-literal -->
<script>
import { _CREATE } from '@shell/config/query-params';
import LabeledSelect from '@shell/components/form/LabeledSelect';
import { saferDump } from '@shell/utils/create-yaml';
import AsyncButton from '@shell/components/AsyncButton';
import { Banner } from '@components/Banner';
import { sortBy } from '@shell/utils/sort';
import { mapGetters } from 'vuex';
import isEmpty from 'lodash/isEmpty';
import {
  K3K_REPO_NAME,
  K3K_REPO_URL,
  K3K_CHART_NAME,
  K3K_CHART_NAMESPACE,
  K3K_VALUES,
  verifyK3kIsInstalled,
  verifyUserCanInstallK3k,
  verifyUserCanCreateK3kClusters
} from '../utils/k3kInstalled';
import { K3K_MAX_VERSION, k3kIndexCharts, k3kChartToInstall, k3kNoChartReason } from '../utils/k3k-chart';
import { PARENT_CLUSTER } from '../labels-annotations';

const DOWNLOAD_MAX_RETRIES = 10;
const DOWNLOAD_FAILED_MAX_RETRIES = 3; // the repo download can temporarily fail and be auto-retried by the backend after 1s, so we poll a few more times
const RETRY_WAIT = 1000;

const INCLUDE_LOCAL = process.env.dev;

export default {
  name: 'K3kHostClusterAndInstallk3k',

  emits: ['update:parentCluster', 'update:k3kInstalled'],

  components: {
    LabeledSelect,
    AsyncButton,
    Banner
  },

  props: {
    // parent cluster's prov cluster
    parentCluster: {
      type:    Object,
      default: () => {
        return {};
      }
    },

    // display-only fallback for edit/view mode if the current user can't fetch the parent prov cluster
    parentClusterDisplayAnnotation: {
      type:    String,
      default: ''
    },

    mode: {
      type:    String,
      default: _CREATE
    },

    // Array of all provisioning clusters
    clusters: {
      type:    Array,
      default: () => []
    },

    k3kInstalled: {
      type:    Boolean,
      default: false
    },

    showButtonOnly: {
      type:    Boolean,
      default: false
    },

    rules: {
      type:    Object,
      default: () => {
        return {};
      }
    }
  },

  created() {
    this.verifyK3kIsInstalledInCurrentCluster();
    if (this.mode === _CREATE) {
      this.getParentClusterInstallationStatus();
    }
  },

  data() {
    // track if k3k chart is present in the currently selected host cluster AND
    // track if the user installed k3k while viewing this page
    return {
      didInstallK3k:           false,
      localParentCluster:      this.parentCluster,
      allParentClusterOptions: [],
      loadingClusters:         false,
      installError:            null,
    };
  },

  watch: {
    parentClusterOptions: {
      handler(neu = []) {
        if (!this.parentCluster?.id && neu.length === 1) {
          this.selectedParentOption = neu[0].value;
        }
      },
      immediate: true
    },
  },

  computed: {
    ...mapGetters({ t: 'i18n/withFallback' }),

    isCreate() {
      return this.mode === _CREATE;
    },

    parentClusterOptions() {
      const out = this.allParentClusterOptions.filter((opt) => {
        if (opt.isVirtual || !opt.isReady || (!INCLUDE_LOCAL && opt.isLocal)) {
          return false;
        }

        if (opt.k3kInstalled) {
          return opt.canCreateK3kClusters;
        }

        return opt.canInstallK3k;
      });

      return sortBy(out, 'label');
    },

    selectedParentOption: {
      // building parentClusterOptions is only done on create because it requires multiple api calls per cluster
      // on edit/view, just show the parent cluster display name
      get() {
        return this.isCreate ? this.parentClusterOptions.find((opt) => opt?.value?.id === this.localParentCluster?.id) : this.getClusterDisplayName(this.parentCluster) || this.parentClusterDisplayAnnotation;
      },
      async set( value ) {
        const fullOption = this.parentClusterOptions.find((opt) => opt?.value?.id === value?.id);

        this.localParentCluster = value;
        this.didInstallK3k = false;
        this.installError = null;

        this.$emit('update:k3kInstalled', fullOption.k3kInstalled);
        // using nextTick here ensures that ClusterPolicy.vue (and any other components that fetch resources in the parent cluster contingent on k3k installation)
        // have up to date install info when they get a new parent cluster id and start re-computing
        this.$nextTick(() => {
          this.$emit('update:parentCluster', value);
        });
      }
    },

    showingInstallationContent() {
      return this.parentCluster && !isEmpty(this.parentCluster) && ((!this.k3kInstalled && this.isCreate) || this.didInstallK3k);
    }
  },

  methods: {
    isEmpty,

    getClusterDisplayName(provCluster) {
      return provCluster?.displayName || provCluster?.name || provCluster?.id;
    },

    // track which clusters already have k3k and the user has permission to create k3k clusters in,
    // and which clusters the user has permission to install k3k in
    async getParentClusterInstallationStatus() {
      this.loadingClusters = true;
      const out = [];

      for (const pCluster of this.clusters) {
        const mgmt = pCluster.mgmt;

        // installk3k function will update k3kInstalled and canCreateK3kCluster properties when it successfully installs k3k
        const [k3kInstalled, canInstallK3k, canCreateK3kClusters] = mgmt?.isReady ? await Promise.all([
          verifyK3kIsInstalled(this.$store, mgmt.id),
          verifyUserCanInstallK3k(this.$store, mgmt.id),
          verifyUserCanCreateK3kClusters(this.$store, mgmt.id)
        ]) : [false, false, false];

        out.push({
          isVirtual: !!pCluster.metadata?.annotations?.[PARENT_CLUSTER],
          isLocal:   pCluster.name === 'local',
          isReady:   mgmt.isReady,
          label:     this.getClusterDisplayName(pCluster),
          value:     pCluster,
          k3kInstalled,
          canInstallK3k,
          canCreateK3kClusters,
        });
      }
      this.allParentClusterOptions = out;
      this.loadingClusters = false;
    },

    async verifyK3kIsInstalledInCurrentCluster(c) {
      try {
        const cluster = c || this.parentCluster;

        await cluster.waitForMgmt();

        const isInstalled = await verifyK3kIsInstalled(this.$store, cluster.mgmt.id);

        if (!isInstalled) {
          this.didInstallK3k = false;
        }
        this.$emit('update:k3kInstalled', isInstalled);
      } catch {
        // timed out trying to load mgmt cluster
        // the list of available clusters is filtered using a property on mgmt so we shouldn't hit this block
      }
    },

    async installK3k(cb) {
      this.installError = null;

      const repo = {
        apiVersion: 'catalog.cattle.io/v1',
        kind:       'ClusterRepo',
        metadata:   { name: K3K_REPO_NAME },
        spec:       {
          url:               K3K_REPO_URL,
          insecurePlainHttp: false
        }
      };

      const cluster = this.parentCluster;

      const normanCluster = await cluster.findNormanCluster();

      await cluster.waitForMgmt();
      const mgmtCluster = cluster.mgmt;
      const k3kRepoUrl = `/k8s/clusters/${ mgmtCluster.id }/v1/catalog.cattle.io.ClusterRepo/${ K3K_REPO_NAME }`;
      let k3kRepo;

      try {
        // create k3k repo crd
        const repoYaml = saferDump(repo);

        await normanCluster.doAction('importYaml', { yaml: repoYaml });

        // poll the repo status until it is downloaded
        // once per second up to 10 retries (11 tries total)
        let downloaded = false;
        let tries = 0;
        let failedTries = 0;
        let refreshed = false;

        while (!downloaded) {
          k3kRepo = await this.$store.dispatch('management/request', {
            url:    k3kRepoUrl,
            method: 'GET',
          });
          const downloadedCondition = k3kRepo.status?.conditions?.find((s) => s.type === 'OCIDownloaded');
          // the condition describes an earlier spec until observedGeneration catches up
          // this is a bit edge-casey but will protect against acting on a stale status if the repo spec was JUST updated
          const processed = downloadedCondition && k3kRepo.status?.observedGeneration >= k3kRepo.metadata?.generation;

          if (processed && downloadedCondition.status === 'True') {
            downloaded = true;
          } else {
            if (processed && !refreshed) {
              // rancher retries most failed oci downloads only after the repo refresh interval
              // a spec change makes it download again immediately
              // same strategy as refresh() in shell/models/catalog.cattle.io.clusterrepo.js
              refreshed = true;
              const forceUpdate = (new Date()).toISOString().replace(/\.\d+Z$/, 'Z');

              await normanCluster.doAction('importYaml', { yaml: saferDump({ ...repo, spec: { ...repo.spec, forceUpdate } }) });
            } else if (processed) {
              // downloadedCondition=== "False" *can* indicate a temporary failure, and the backend might be automatically retrying
              // in which case we should just wait instead of immediately failing
              failedTries++;

              if (failedTries > DOWNLOAD_FAILED_MAX_RETRIES) {
                throw new Error(this.t('k3k.errors.repoDownloadFailed', { repo: K3K_REPO_NAME, message: downloadedCondition.message }));
              }
            } else {
              tries++;

              if (tries > DOWNLOAD_MAX_RETRIES) {
                throw new Error(this.t('k3k.errors.repoNotDownloaded', { repo: K3K_REPO_NAME }));
              }
            }
            await new Promise((resolve) => setTimeout(resolve, RETRY_WAIT));
          }
        }


        const repoReq = await this.$store.dispatch('management/request', {
          url:    k3kRepo.links?.index,
          method: 'GET',
        });
        const charts = k3kIndexCharts(repoReq);
        // find the latest k3k chart that does not exceed the extension's major/minor version
        const k3kChart = k3kChartToInstall(charts);

        if (!k3kChart) {
          const reason = k3kNoChartReason(charts);

          throw new Error(this.t(`k3k.errors.${ reason }`, {
            repo: K3K_REPO_NAME, maxVersion: K3K_MAX_VERSION, versions: charts.map((chart) => chart.version).join(', ')
          }));
        }

        // eslint-disable-next-line no-console
        console.log('Installing k3k version...', k3kChart.version);

        // install k3k chart
        const installRequest = {
          charts: [
            {
              annotations: {
                'catalog.cattle.io/ui-source-repo':      K3K_REPO_NAME,
                'catalog.cattle.io/ui-source-repo-type': 'cluster'
              },
              chartName:   k3kChart.name,
              releaseName: K3K_CHART_NAME,
              version:     k3kChart.version,
              values:      K3K_VALUES
            }
          ],
          disableOpenAPIValidation: false,
          namespace:                K3K_CHART_NAMESPACE,
          noHooks:                  false,
          skipCRDs:                 false,
          timeout:                  '600s',
          wait:                     true
        };

        let installTries = 0;
        const INSTALL_MAX_TRIES = 3;

        while (!this.didInstallK3k && installTries <= INSTALL_MAX_TRIES) {
          installTries++;
          try {
            const res = await this.$store.dispatch('management/request', {
              url:    `${ k3kRepoUrl }?action=install`,
              method: 'POST',
              data:   installRequest
            });

            if (res._status === 201) {
              this.$emit('update:k3kInstalled', true);

              this.didInstallK3k = true;
            }
          } catch (err) {
            if (installTries >= INSTALL_MAX_TRIES) {
              throw (err);
            }
            await new Promise((resolve) => setTimeout(resolve, RETRY_WAIT));
          }
        }

        if (this.didInstallK3k) {
          const currentOpt = this.allParentClusterOptions.find((opt) => opt.value.id === cluster.id);

          if (currentOpt) {
            currentOpt.k3kInstalled = true;
            currentOpt.canCreateK3kClusters = true;
          }
          cb(true);
        } else {
          cb(false);
        }
      } catch (e) {
        this.installError = `${ this.t('k3k.errors.installingK3k') }: ${ e?.message || e }`;

        cb(false);
      }
    },
  },
};
</script>

<template>
  <div class="install-k3k">
    <Banner
      v-if="installError"
      class="install-error"
      data-testid="k3k-install-error-banner"
      color="error"
      role="alert"
      :label="installError"
      :closable="true"
      @close="installError = null"
    />
    <div
      class="k3k-input-row"
      :class="{ 'k3k-half': !showingInstallationContent }"
    >
      <div
        v-if="!showButtonOnly"
        class="k3k-half"
      >
        <t
          raw
          k="k3k.hostCluster.description"
          class="text-deemphasized"
        />
        <LabeledSelect
          v-model:value="selectedParentOption"
          class="mmt-1"
          data-testid="k3k-host-cluster-select"
          label-key="k3k.hostCluster.label"
          :mode="mode"
          :disabled="!isCreate"
          :options="parentClusterOptions"
          :loading="loadingClusters"
          :rules="rules.hostCluster"
          required
        />
      </div>
      <div
        v-if="parentCluster && !isEmpty(parentCluster) && !k3kInstalled && isCreate"
        class="centered text-label"
      >
        <t
          v-if="!showButtonOnly"
          raw
          k="k3k.hostCluster.notInstalled"
        />
        <AsyncButton
          type="button"
          data-testid="install-k3k-button"
          class="btn-sm role-tertiary mt-5"
          mode="install"
          :action-label="t('k3k.hostCluster.installK3k')"
          @click="installK3k"
        />
      </div>
      <div
        v-else-if="parentCluster && !isEmpty(parentCluster) && didInstallK3k"
        class="centered"
        data-testid="k3k-install-succeeded"
      >
        <span> <i class="icon icon-checkmark text-success mr-5" />{{ t('k3k.hostCluster.didInstall') }}</span>
      </div>
    </div>
  </div>
</template>

<style lang="scss" scoped>
.install-k3k {
  display: flex;
  flex-direction: column;
  gap: var(--gap-md);
  align-self: stretch;

  &>.install-error {
    margin: 0;
  }
}
</style>
